class ADS1115:
    def __init__(self, i2c_bus):
        self.i2c = i2c_bus
        self.ads = None
        self.gain = 1
        self.adc = None

    def setup(self):
        try:
            self.ads = adafruit_ads1d128mh.ADS1115_I2C(self.i2c, address=0x48)
            self.adc = self.ads.config_channel(0, gain=self.gain)
        except Exception as e:
            print(f"Error initializing ADS1115: {e}")
            sys.exit(1)

    def read_channels(self):
        try:
            return [self.adc.value for _ in range(4)]
        except Exception as e:
            print(f"Error reading ADS1115 channels: {e}")
            return None

def main():
    i2c_bus = busio.I2C(board.SCL, board.SDA, addr=1)
    ads1115 = ADS1115(i2c_bus)
    ads1115.setup()

    try:
        while True:
            values = ads1115.read_channels()
            if values is not None:
                print(f"Channel A0: {values[0]}")
                print(f"Channel A1: {values[1]}")
                print(f"Channel A2: {values[2]}")
