import time
import RPi.GPIO as GPIO
from gpiozero import MCP3008
import paho.mqtt.client as mqtt
import sys
import signal

class MQ2Sensor:
    def __init__(self, adc_channel=0, cs=0):
        self.adc = MCP3008(channel=adc_channel, cs=cs)
        self.alert_levels = {
            "safe": (0, 150),
            "warning": (150, 399),
            "danger": (400, 1023)
        }
        self.last_reading = None

    def read_raw(self):
        return self.adc.value

    def read_concentration(self):
        raw = self.read_raw()
        if raw is None:
            return None
        return self._convert_raw_to_ppm(raw)

    def _convert_raw_to_ppm(self, raw):
        # This is a simplified conversion formula for MQ-2 gas sensor
        # The actual conversion formula may vary depending on the sensor's characteristics
        return (raw / 1023) * 100

    def get_alert_level(self):
        if self.last_reading is None:
            return "unknown"
        raw = self.read_raw()
        if raw is None:
            return "unknown"
        ppm = self.read_concentration()
        if ppm is None:
            return "unknown"
        for level, (low, high) in self.alert_levels.items():
            if low <= ppm <= high:
                return level
        return "unknown"

    def run(self):
        try:
            while True:
                raw = self.read_raw()
                if raw is None:
                    print("SPI error: Unable to read ADC value")
                    continue
                ppm = self.read_concentration()
                if ppm is None:
                    print("SPI error: Unable to convert ADC value to ppm")
                    continue
                alert_level = self.get_alert_level()
                print(f"Raw: {raw}, ppm: {ppm:.2f}, Alert Level: {alert_level}")
                time.sleep(0.5)
        except KeyboardInterrupt:
            print("Exiting...")
        except Exception as e:
            print(f"An error occurred: {e}")
        finally:
            self.adc.close()
            GPIO.cleanup()

def main():
    sensor = MQ2Sensor(adc_channel=0, cs=0)
    sensor.run()

if __name__ == "__main__":
    main()

import time
