        logging.info(f"Current weather: {weather_data['weather'][0]['description']}")

        # Check rainfall in last hour
        last_hour_rainfall = 0
        for i in range(4):
            channel = SPI_CHANNELS[i]
            value = spi.value(channel)
            if value is None:
                logging.error(f"Failed to read SPI channel {channel}")
                continue
            last_hour_rainfall += value * 0.01  # Convert to mm

        if last_hour_rainfall > 2:
            logging.info("Rainfall in last hour exceeds 2mm, skipping irrigation")
            continue

        # Check camera parity
        current_second = time.localtime()[5]
        if current_second % 2 == 0:
            camera.capture('camera_image.jpg', 'jpeg')
            logging.info(f"Captured camera image at {time.strftime('%Y-%m-%d %H:%M:%S')}")
        else:
            logging.info("No camera image captured")

        # Check each zone
        for zone in range(4):
            channel = SPI_CHANNELS[zone]
            value = spi.value(channel)
            if value is None:
                logging.error(f"Failed to read SPI channel {channel}")
                continue
            if value < 0.5:  # 50% threshold for irrigation
                logging.info(f"Irrigating zone {zone}...")
                relays[zone + 1].on()
                time.sleep(600)  # 10 minutes
                relays[zone + 1].off()
