# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SENSOR_PIN = 4
DHT22_SENSOR = "DHT22"
TEMP_MIN = -40
TEMP_MAX = 80
HUMID_MIN = 0
HUMID_MAX = 100
SAMPLING_INTERVAL = 60
MAVING_AVERAGE_WINDOW = 5
RETRY_DELAY = [1, 3, 9]
MAX_RETRIES = 3
RETRY_ATTEMPTS = 3
POST_URL = "https://your-webhook-url.com"
CONFIG_FILE = "config.json"

# Load configuration
try:
    with open(CONFIG_FILE, "r") as f:
        config = json.load(f)
    POST_URL = config["webhook_url"]
except FileNotFoundError:
    logging.error("Config file not found")
    sys.exit(1)

# GPIO setup
try:
    import RPi.GPIO as GPIO
except ImportError:
    logging.error("RPi.GPIO not installed")
    sys.exit(1)

GPIO.setmode(GPIO.BCM)
GPIO.setup(SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_OFF)

# DHT22 sensor class
class DHT22Sensor:
    def __init__(self, pin):
        self.pin = pin
        self.last_read = None
        self.last_temp = None
        self.last_hum = None
        self.last_time = None

    def read(self):
        try:
            humidity, temperature = self._read()
            return humidity, temperature
        except (OSError, RuntimeError) as e:
            logging.error(f"Sensor read error: {e}")
            return self._simulate()

    def _read(self):
        humidity, temperature = self._dht22_read()
        self.last_time = datetime.datetime.now()
        return humidity, temperature

    def _simulate(self):
        # Simulate sensor readings
        if self.last_time is None:
            return 60, 20
        else:
            now = datetime.datetime.now()
            elapsed = (now - self.last_time).total_seconds()
            if elapsed < 60:
                return 60, 20
            else:
                return 60 + random.uniform(-10, 10), 20 + random.uniform(-10, 10)

    def _dht22_read(self):
        # Dummy implementation for DHT22
        return 60, 20

    def get_average(self):
        if self.last_read is None:
            return None
        else:
            values = [self.last_temp, self.last_hum]
            for _ in range(MAVING_AVERAGE_WINDOW - 2):
                values.append(self.last_read[1])
                values.append(self.last_read[0])
            return sum(values) / len(values)

# Moving average calculation
def moving_average(data):
    if len(data) < MAVING_AVERAGE_WINDOW:
        return None
    return sum(data[-MAVING_AVERAGE_WINDOW:]) / MAVING_AVERAGE_WINDOW

# Webhook post function
def post_webhook(data):
    for delay in RETRY_DELAY:
        try:
            response = requests.post(POST_URL, json=data, timeout=5)
            if response.status_code == 200:
                logging.info(f"Webhook sent successfully")
                return
            else:
                logging.warning(f"Webhook failed with status {response.status_code}")
        except requests.exceptions.RequestException as e:
            logging.error(f"Webhook request failed: {e}")
        time.sleep(delay)

# Signal handler
def signal_handler(sig, frame):
    logging.info("Received signal, exiting")
    GPIO.cleanup()
    sys.exit(0)

# Main loop
def main():
    sensor = DHT22Sensor(SENSOR_PIN)
    data = {"temperature": None, "humidity": None, "moving_average": None}
    while True:
        try:
            humidity, temperature = sensor.read()
            if temperature < TEMP_MIN or temperature > TEMP_MAX:
                logging.error(f"Temperature out of range: {temperature}°C")
                data["temperature"] = None
            elif humidity < HUMID_MIN or humidity > HUMID_MAX:
                logging.error(f"Humidity out of range: {humidity}%")
                data["humidity"] = None
            else:
                data["temperature"] = temperature
                data["humidity"] = humidity
                data["moving_average"] = moving_average([temperature, humidity] + [sensor.last_temp, sensor.last_hum] * (MAVING_AVERAGE_WINDOW - 4))
                logging.info(f"Temperature: {temperature}°C, Humidity: {humidity}%")
                post_webhook(data)
        except Exception as e:
            logging.error(f"Main loop error: {e}")
        time.sleep(SAMPLING_INTERVAL)

# Start main loop
if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

