import time
import sys
import os
import signal
import RPi.GPIO as GPIO
from gpiozero import PWMDevice
from paho.mqtt.client import MQTTClient
import vcgencmd

# Set up GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(14, GPIO.OUT)
fan = PWMDevice(14)

# MQTT client setup
mqtt_client = MQTTClient("test", "localhost", port=1883)
mqtt_client.connect()
mqtt_client.loop_start()

# Function to read temperature
def read_temperature():
    try:
        temp = vcgencmd.measure_temp()
        return float(temp.split('=')[1].split('\'')[0])
    except (vcgencmd.VcgencmdError, ValueError):
        print("Failed to read temperature. Trying again...")
        return read_temperature()

# Function to compute duty cycle
def compute_duty_cycle(temp):
    if temp < 50:
        return 0.0
    elif temp < 60:
        return 0.2
    elif temp < 70:
        return 0.4
    elif temp < 80:
        return 0.6
    elif temp < 90:
        return 0.8
    else:
        return 1.0

# Function to set fan speed
def set_fan_speed(duty_cycle):
    fan.pulse_width_percent(duty_cycle)

# Function to log temperature and fan speed
def log_data(temp, duty_cycle):
    print(f"Temperature: {temp}°C, Fan Speed: {duty_cycle*100}%")

# Main loop
while True:
    try:
        temp = read_temperature()
        duty_cycle = compute_duty_cycle(temp)
        set_fan_speed(duty_cycle)
        log_data(temp, duty_cycle)
    except Exception as e:
        print(f"An error occurred: {e}")
        time.sleep(5)

# Cleanup GPIO and MQTT
def cleanup():
    fan.stop()
    GPIO.cleanup()
    mqtt_client.loop_stop()
    mqtt_client.disconnect()

# Signal handlers
def signal_handler(sig, frame):
    cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

try:
    while True:
        time.sleep(5)
except KeyboardInterrupt:
    signal_handler(0, None)
except Exception as e:
    print(f"An error occurred: {e}")
    cleanup()
    sys.exit(1)

