        line = ser.readline().decode('utf-8').strip()
        if line:
            try:
                temp, humidity = map(float, line.split(','))
                if temp > 30.0 or humidity > 70.0:
                    publish.single(topic=MQTT_TOPIC, payload=f"{temp},{humidity}", hostname=MQTT_HOST, port=MQTT_PORT, retain=True)
