import http.server
import socketserver
import sys
import signal
import threading
from gpiozero import LED
from http import HTTPStatus

# LED object at module level
led = None

def init_led():
    global led
    try:
        led = LED(17)
    except Exception as e:
        print(f"Error initializing LED: {e}")
        sys.exit(1)

def handle_sigint(sig, frame):
    global led
    if led:
        led.close()
    sys.exit(0)

def handle_sigterm(sig, frame):
    global led
    if led:
        led.close()
    sys.exit(0)

def run_server():
    global led
    init_led()

    class LightHandler(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path == '/':
                self.send_response(HTTPStatus.OK)
                self.send_header("Content-type", "text/html")
                self.end_headers()
                self.wfile.write(b"<html><body><h1>Light Control</h1><p><a href='/light_on'>Turn LED On</a><a href='/light_off'>Turn LED Off</a></p></body></html>".encode())
            elif self.path == '/light_on':
                if led.is_lit:
                    self.send_response(HTTPStatus.OK)
                    self.send_header("Content-type", "text/html")
                    self.end_headers()
                    self.wfile.write(b"LED is already on. Click <a href='/'>back</a>.".encode())
                else:
                    led.on()
                    self.send_response(HTTPStatus.OK)
                    self.send_header("Content-type", "text/html")
                    self.end_headers()
                    self.wfile.write(b"LED is now on. Click <a href='/'>back</a>.".encode())
            elif self.path == '/light_off':
                if not led.is_lit:
                    self.send_response(HTTPStatus.OK)
                    self.send_header("Content-type", "text/html")
                    self.end_headers()
                    self.wfile.write(b"LED is already off. Click <a href='/'>back</a>.".encode())
                else:
                    led.off()
                    self.send_response(HTTPStatus.OK)
                    self.send_header("Content-type", "text/html")
                    self.end_headers()
                    self.wfile.write(b"LED is now off. Click <a href='/'>back</a>.".encode())
            else:
                self.send_response(HTTPStatus.NOT_FOUND)
                self.send_header("Content-type", "text/html")
                self.end_headers()
                self.wfile.write(b"Page not found. Click <a href='/'>back</a>.".encode())

    with socketserver.TCPServer(("", 8080), LightHandler) as httpd:
        httpd.serve_forever()

def main():
    signal.signal(signal.SIGINT, handle_sigint)
    signal.signal(signal.SIGTERM, handle_sigterm)

    try:
        threading.Thread(target=run_server).start()
        while True:
            pass
    except KeyboardInterrupt:
        if led:
            led.close()
        sys.exit(0)

if __name__ == "__main__":
    main()

