# Define the button and its configuration
button = Button(17, pull_up=True)

# Define the cooldown timer
cooldown_start = None
cooldown_duration = timedelta(milliseconds=1000)

# Define the debounce timer
debounce_start = None

def handle_falling_edge():
    global debounce_start, cooldown_start
    debounce_start = datetime.now()
    if debounce_start - cooldown_start > cooldown_duration:
        try:
            # Send POST request
            response = requests.post(
                'http://example.com/alert',
                json={"alert": "Rain detected at manufacturing line"}
            )
            if response.status_code == 200:
                logging.info(f"Alert sent successfully")
            else:
                logging.error(f"Failed to send alert: {response.status_code}")
        except RequestException as e:
            logging.error(f"Network error: {e}")
        finally:
            cooldown_start = datetime.now()

def run():
    global cooldown_start, debounce_start
    while True:
        try:
            # Check for falling edge
            if button.is_pressed:
                if debounce_start is None or (datetime.now() - debounce_start) > timedelta(milliseconds=500):
                    handle_falling_edge()
            time.sleep(0.1)
        except KeyboardInterrupt:
            logging.info("User interrupted the program")
            break

