# Import necessary modules
import RPi.GPIO as GPIO
from gpiozero import LED
from time import sleep
import paho.mqtt.client as mqtt
import sys

# Define the LED object
led = LED(17)

# Function to turn the LED on
def turn_on_led():
    # Set the LED to on state
    led.on()
    print("LED is on")

# Function to turn the LED off
def turn_off_led():
    # Set the LED to off state
    led.off()
    print("LED is off")

# Function to handle MQTT connection and publish a message
def publish_to_mqtt():
    # Create a MQTT client
    client = mqtt.Client()
    # Connect to the MQTT broker
    client.connect("localhost", 1883)
    # Subscribe to a topic
    client.subscribe("led_state")
    # Infinite loop to receive messages
    while True:
        # Receive a message
        message = client.wait_msg()
        # If the message is "ON", turn the LED on
        if message.payload.decode() == "ON":
            turn_on_led()
        # If the message is "OFF", turn the LED off
        elif message.payload.decode() == "OFF":
            turn_off_led()
        # If the message is "PUBLISH", publish a message
        elif message.topic == "led_state" and message.payload.decode() == "PUBLISH":
            client.publish("led_state", "ON")
            turn_on_led()
        # If the message is "RECEIVE", receive a message
