import time
import json
import socket
import threading
import sys
import signal
import logging
import math
import numpy as np

# Set up logging
logging.basicConfig(filename='notification_light.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define the color mapping
def color_mapping(value):
    if value > 66:
        return (1, 0, 0)  # Red
    elif value > 33:
        return (0, 1, 0)  # Green
    else:
        return (0, 0, 1)  # Blue

# Define the PWM class
class PWM:
    def __init__(self, pin):
        self.pin = pin
        self.pwm = None

    def start(self, duty_cycle):
        if self.pwm is None:
            self.pwm = GPIO.PWM(self.pin, 1000)
            self.pwm.start(duty_cycle)

    def stop(self):
        if self.pwm is not None:
            self.pwm.stop()

# Define the LED class
class LED:
    def __init__(self, pin):
        self.pin = pin
        self.pwm = None

    def set_color(self, r, g, b):
        if self.pwm is None:
            self.pwm = PWM(self.pin)
        self.pwm.start(r)

    def stop(self):
        if self.pwm is not None:
            self.pwm.stop()

# Define the socket client
class SocketClient:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.socket = None
        self.lock = threading.Lock()
        self.data = None

    def connect(self):
        try:
            self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.socket.connect((self.host, self.port))
            return True
        except socket.error as e:
            logging.error(f"Socket connection error: {e}")
            return False

    def receive(self):
        try:
            while True:
                data = self.socket.recv(1024)
                if not data:
                    break
                try:
                    self.data = json.loads(data.decode('utf-8'))
                except json.JSONDecodeError as e:
                    logging.error(f"JSON decode error: {e}")
                    continue
                self.lock.acquire()
                self.process_data()
                self.lock.release()
        except socket.error as e:
            logging.error(f"Socket receive error: {e}")
        finally:
            self.socket.close()

    def process_data(self):
        if self.data is None:
            return
        for key, value in self.data.items():
            if key == 'cpu_usage':
                self.led1.set_color(*color_mapping(value))
            elif key == 'memory_usage':
                self.led2.set_color(*color_mapping(value))
            elif key == 'disk_io':
                self.led3.set_color(*color_mapping(value))

# Define the signal handlers
def signal_handler(sig, frame):
    logging.info("Received signal, stopping PWM and exiting")
    for led in [led1, led2, led3]:
        led.stop()
    for pwm in [pwm1, pwm2, pwm3]:
        pwm.stop()
    sys.exit(0)

# Define the main function
def main():
    global led1, led2, led3, pwm1, pwm2, pwm3

    # Initialize GPIO
    try:
        import RPi.GPIO as GPIO
    except ImportError:
        logging.error("RPi.GPIO not found")
        sys.exit(1)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    # Initialize LEDs
    led1 = LED(17)
    led2 = LED(22)
    led3 = LED(5)

    # Initialize PWMs
    pwm1 = PWM(18)
    pwm2 = PWM(23)
    pwm3 = PWM(13)

    # Set up signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize socket client
    client = SocketClient('192.168.1.100', 5000)
    if not client.connect():
        logging.error("Socket connection failed")
        sys.exit(1)

    # Start receive thread
    receive_thread = threading.Thread(target=client.receive)
    receive_thread.start()

    # Main loop
    while True:
        time.sleep(1)

if __name__ == "__main__":
    main()

