import time
import logging
import signal
import sys
import threading
import RPi.GPIO as GPIO
from gpiozero import MotionSensor
from datetime import datetime, timedelta

class MotionSensorMonitor:
    def __init__(self, gpio_pin=23):
        self.motion_sensor = MotionSensor(gpio_pin)
        self.motion_detected = False
        self.motion_detected_since = datetime.now()
        self.tally = 0
        self.last_print_time = datetime.now()
        self.setup_gpio()

    def setup_gpio(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.motion_sensor.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

    def poll_sensor(self):
        while True:
            if self.motion_sensor.value:
                self.motion_detected = True
                self.motion_detected_since = datetime.now()
            else:
                self.motion_detected = False
                self.motion_detected_since = datetime.now() - timedelta(seconds=30)
            if self.motion_detected and (datetime.now() - self.motion_detected_since).total_seconds() < 200:
                self.tally += 1
            if (datetime.now() - self.last_print_time).total_seconds() >= 10:
                self.print_tally()
            if (datetime.now() - self.motion_detected_since).total_seconds() >= 30 and self.motion_detected:
                self.motion_detected = False
                self.motion_detected_since = datetime.now() - timedelta(seconds=30)

    def print_tally(self):
        logging.info(f"Current tally: {self.tally}")
        self.last_print_time = datetime.now()

    def cleanup(self):
        logging.info("Exiting...")
        GPIO.cleanup()
        sys.exit(0)

    def signal_handler(self, signum, frame):
        logging.info("Received signal, exiting...")
        self.cleanup()

    def run(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)
        threading.Thread(target=self.poll_sensor).start()
        try:
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            self.cleanup()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    monitor = MotionSensorMonitor()
    monitor.run()

import time
import logging
import random
import threading
from gpiozero import InputDevice
from picamera2 import PiCamera2
from paho.mqtt import MQTTClient
from datetime import datetime
from enum import Enum
from contextlib import contextmanager

ACTUATORS = {
    1: lambda: print("Light activated"),  # Simulated function
    2: lambda: print("Sound activated"),  # Simulated function
    3: lambda: print("Motor activated"),  # Simulated function
}

class DebouncedSensor:
    def __init__(self, pin):
        self.pin = pin
        self.last_state = None
        self.last_time = None

    def read_sensor(self):
        state = self.pin.value
        if state != self.last_state:
            self.last_state = state
            self.last_time = datetime.now()
        return state

    def debounce(self):
        if self.last_time is not None:
            current_time = datetime.now()
            if (current_time - self.last_time).total_seconds() > 0.1:
                self.last_state = None
                self.last_time = None

@contextmanager
def gpio_setup():
    try:
        yield
    finally:
        for pin in [17, 18]:
            GPIO.output(pin, GPIO.IN)

class ArtInstallation:
    def __init__(self):
        self.sensors = [DebouncedSensor(17), DebouncedSensor(18)]
        self.camera = PiCamera2()
        self.mqtt_client = MQTTClient("art-installation", "localhost", 1883)
        self.mqtt_client.connect()
        self.logger = logging.getLogger("art_installation")
        self.logger.setLevel(logging.INFO)
        self.logger.addHandler(logging.FileHandler("art_installation.log"))

    def run(self):
        try:
            with gpio_setup() as _:
                while True:
                    for i, sensor in enumerate(self.sensors):
                        if sensor.read_sensor():
                            self.logger.info(f"Intrusion Detected - Sensor {i+1} triggered")
                            self.logger.info(f"Pin: {sensor.pin}")
                            actuator = random.choice(list(ACTUATORS.keys()))
                            ACTUATORS[actuator]()
                            self.mqtt_client.publish(f"art-installation/intrusion", f"Intrusion Detected - Sensor {i+1} triggered")
                            self.mqtt_client.publish(f"art-installation/intrusion/pin", str(sensor.pin))
                    time.sleep(0.05)
        except KeyboardInterrupt:
            self.logger.info("Graceful shutdown")
        except Exception as e:
            self.logger.error(f"An error occurred: {e}")
            if isinstance(e, RuntimeError) or isinstance(e, ConnectionError):
                self.logger.error("Exiting due to error")
                self.mqtt_client.disconnect()
                self.camera.close()
                exit(1)
            else:
                self.logger.info("Continuing to run")

if __name__ == "__main__":
    art_installation = ArtInstallation()
    art_installation.run()

