        angles = [0, 45, 90, 135, 180, 135, 90, 45, 0]
        servo = ServoSweep(servo_pin=18, pwm_freq=50, servo_type='SG90')
        servo.sweep(angles)
    except KeyboardInterrupt:
        servo.stop()
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        servo.stop()

if __name__ == "__main__":
    main()

import serial
import time
import struct
import paho.mqtt.client as mqtt
import signal
import sys
import logging
import os

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ModbusRTUServo:
    def __init__(self, slave_address=1, baud_rate=115200, parity='N', data_bits=8, stop_bits=1, timeout=1):
        self.slave_address = slave_address
        self.baud_rate = baud_rate
        self.parity = parity
        self.data_bits = data_bits
        self.stop_bits = stop_bits
        self.timeout = timeout
        self.serial_port = None
        self.mqtt_client = None
        self.mqtt_topic = "motor_feedback"
        self.mqtt_client_on_connect = None
        self.mqtt_client_on_message = None

        # Set up signal handlers
        signal.signal(signal.SIGINT, self._handle_sigint)
        signal.signal(signal.SIGTERM, self._handle_sigterm)

    def _handle_sigint(self, *args):
        self._shutdown()

    def _handle_sigterm(self, *args):
        self._shutdown()

    def _shutdown(self):
        if self.serial_port:
            self.serial_port.close()
        if self.mqtt_client:
            self.mqtt_client.disconnect()
        logging.info("Shutdown complete")

    def _send_command(self, command):
        try:
            if not self.serial_port:
                raise ValueError("Serial port not initialized")
            self.serial_port.flush()
            self.serial_port.write(struct.pack('>B', self.slave_address) + struct.pack('>B', command))
            self.serial_port.flush()
            return self.serial_port.read(2)
        except serial.SerialException as e:
            logging.error(f"Serial port error: {e}")
            raise
        except Exception as e:
            logging.error(f"Error sending command: {e}")
            raise

    def _read_response(self, expected_response_length):
        try:
            if not self.serial_port:
                raise ValueError("Serial port not initialized")
            self.serial_port.flush()
            response = self.serial_port.read(expected_response_length)
            if len(response) != expected_response_length:
                raise ValueError(f"Expected {expected_response_length} bytes, got {len(response)}")
            return response
        except serial.SerialException as e:
            logging.error(f"Serial port error: {e}")
            raise
        except Exception as e:
            logging.error(f"Error reading response: {e}")
            raise

    def _read_feedback(self):
        try:
            if not self.serial_port:
                raise ValueError("Serial port not initialized")
            self.serial_port.flush()
            feedback = self.serial_port.read(2)
            if len(feedback) != 2:
                raise ValueError(f"Expected 2 bytes, got {len(feedback)}")
            return feedback
        except serial.SerialException as e:
            logging.error(f"Serial port error: {e}")
            raise
        except Exception as e:
            logging.error(f"Error reading feedback: {e}")
            raise

    def _connect_to_mqtt(self, mqtt_host, mqtt_port, mqtt_user, mqtt_password):
        try:
            self.mqtt_client = mqtt.Client()
            self.mqtt_client.on_connect = self.mqtt_client_on_connect
            self.mqtt_client.on_message = self.mqtt_client_on_message
            self.mqtt_client.connect(mqtt_host, mqtt_port, keepalive=60)
            self.mqtt_client.loop_start()
        except Exception as e:
            logging.error(f"MQTT connection error: {e}")
            raise

    def _disconnect_from_mqtt(self):
        if self.mqtt_client:
            self.mqtt_client.disconnect()
            self.mqtt_client.loop_stop()

    def _register_mqtt_callbacks(self, mqtt_client_on_connect, mqtt_client_on_message):
        self.mqtt_client_on_connect = mqtt_client_on_connect
        self.mqtt_client_on_message = mqtt_client_on_message

    def _send_mqtt_message(self, topic, payload):
        try:
            if not self.mqtt_client:
                raise ValueError("MQTT client not initialized")
            self.mqtt_client.publish(topic, payload)
        except Exception as e:
            logging.error(f"MQTT message error: {e}")
            raise

    def _read_mqtt_feedback(self):
        try:
            if not self.mqtt_client:
                raise ValueError("MQTT client not initialized")
            feedback = self.mqtt_client.subscribe(self.mqtt_topic)
            if feedback:
                return self.mqtt_client.wait_for_message()
            else:
                return None
        except Exception as e:
            logging.error(f"MQTT feedback error: {e}")
            raise

    def _register_serial_port(self, port):
        try:
            self.serial_port = serial.Serial(port, self.baud_rate, parity=self.parity, bytesize=self.data_bits, stopbits=self.stop_bits, timeout=self.timeout)
            self.serial_port.flush()
        except serial.SerialException as e:
            logging.error(f"Serial port initialization error: {e}")
            raise
        except Exception as e:
            logging.error(f"Serial port initialization error: {e}")
            raise

    def _register_mqtt_client(self, mqtt_host, mqtt_port, mqtt_user, mqtt_password):
        self._connect_to_mqtt(mqtt_host, mqtt_port, mqtt_user, mqtt_password)
        self._register_mqtt_callbacks(self.mqtt_client_on_connect, self.mqtt_client_on_message)

    def _register_serial_port_and_mqtt_client(self, port, mqtt_host, mqtt_port, mqtt_user, mqtt_password):
        self._register_serial_port(port)
        self._register_mqtt_client(mqtt_host, mqtt_port, mqtt_user, mqtt_password)

    def _move_motor(self, target_position):
        try:
            if not self.serial_port:
                raise ValueError("Serial port not initialized")
            self._send_command(0x00)  # Reset
            self._send_command(0x01)  # Set target position
            self._send_command(target_position)
            self._send_command(0x02)  # Move
            feedback = self._read_response(2)
            return feedback
        except Exception as e:
            logging.error(f"Motor move error: {e}")
            raise

    def _read_motor_feedback(self):
        try:
            if not self.serial_port:
                raise ValueError("Serial port not initialized")
            feedback = self._read_feedback()
            return feedback
        except Exception as e:
            logging.error(f"Motor feedback error: {e}")
            raise

    def _read_mqtt_motor_feedback(self):
        try:
            if not self.mqtt_client:
                raise ValueError("MQTT client not initialized")
            feedback = self._read_mqtt_feedback()
            return feedback
        except Exception as e:
            logging.error(f"MQTT motor feedback error: {e}")
            raise

    def _move_motor_and_read_feedback(self, target_position):
        try:
            feedback = self._move_motor(target_position)
            return feedback
        except Exception as e:
            logging.error(f"Motor move and read feedback error: {e}")
            raise

    def _move_motor_and_read_feedback_via_mqtt(self, target_position):
        try:
            if not self.mqtt_client:
                raise ValueError("MQTT client not initialized")
            self._send_mqtt_message(self.mqtt_topic, str(target_position))
            feedback = self._read_mqtt_motor_feedback()
            return feedback
        except Exception as e:
            logging.error(f"Motor move and read feedback via MQTT error: {e}")
            raise

    def _demo(self):
        try:
            self._register_serial_port_and_mqtt_client("/dev/serial0", "mqtt.example.com", 1883, "user", "password")
            self._move_motor(1000)
            feedback = self._read_motor_feedback()
            print(f"Motor feedback: {feedback}")
            feedback = self._read_mqtt_motor_feedback()
            print(f"MQTT motor feedback: {feedback}")
        except Exception as e:
            logging.error(f"Demo error: {e}")
            raise
        finally:
            self._disconnect_from_mqtt()
            self._shutdown()

if __name__ == '__main__':
    try:
        modbus_servo = ModbusRTUServo()
        modbus_servo._demo()
    except Exception as e:
        logging.error(f"Main error: {e}")
        sys.exit(1)

