import time
import serial
import json
import os
import signal
import datetime
import logging
from gpiozero import LED
from picamera2 import PiCamera2
from paho.m2mqtt import mqtt
from io import StringIO
from contextlib import contextmanager

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Set up GPIO LED
led = LED(17)

# Set up MQTT client
mqtt_client = mqtt.Client()
mqtt_client.connect('localhost', 1883, keepalive=60)

# Set up serial port
ser = None
def setup_serial():
    global ser
    try:
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
        return False
    return True

@contextmanager
def open_serial():
    global ser
    if not setup_serial():
        return
    try:
        yield
    finally:
        if ser:
            ser.close()

@contextmanager
def open_log_file():
    filename = 'co2_readings_log.txt'
    try:
        with open(filename, 'a') as f:
            yield f
    except IOError as e:
        logging.error(f"Failed to open log file: {e}")
        return

@contextmanager
def open_mqtt_connection():
    try:
        mqtt_client.loop_start()
        yield
    finally:
        mqtt_client.loop_stop()
        mqtt_client.disconnect()

@contextmanager
def open_pi_camera():
    try:
        camera = PiCamera2()
        camera.resolution = (1920, 1080)
        yield camera
    finally:
        camera.close()

def read_serial():
    try:
        with open_serial() as ser:
            line = ser.readline().decode('ascii', errors='replace')
            if line:
                try:
                    co2 = int(line.strip())
                    return co2
                except ValueError:
                    logging.warning(f"Invalid CO2 value: {line.strip()}")
                    return None
            else:
                logging.warning("No data received")
                return None
    except Exception as e:
        logging.error(f"Serial read error: {e}")
        return None

def write_to_log(co2):
    try:
        with open_log_file() as f:
            timestamp = datetime.datetime.now().isoformat()
            f.write(f"{timestamp} {co2}\n")
    except Exception as e:
        logging.error(f"Log file write error: {e}")

def handle_signal(sig, frame):
    logging.info("Received signal, shutting down...")
    mqtt_client.loop_stop()
    mqtt_client.disconnect()
    if ser:
        ser.close()
    if camera:
        camera.close()
    os._exit(0)

def main():
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    while True:
        co2 = read_serial()
        if co2 is not None:
            write_to_log(co2)
            logging.info(f"CO2 reading: {co2} ppm")
            led.on()
            time.sleep(5)
            led.off()
        else:
            logging.info("No valid CO2 reading received")

if __name__ == "__main__":
    main()

