import serial
import time
import sys
import re
from gpiozero import Button
from paho.mqtt.client import MQTTClient
from gpiozero import LED

# Define the LED and Button for the Pi
led = LED(17)
button = Button(22)

# Define the MQTT client
mqtt_client = None

def connect_to_mqtt():
    global mqtt_client
    mqtt_client = MQTTClient("my_mqtt_client", "broker.hivemq.com", port=1883)
    mqtt_client.connect()
    mqtt_client.loop_start()

def disconnect_from_mqtt():
    global mqtt_client
    if mqtt_client is not None:
        mqtt_client.disconnect()
        mqtt_client.loop_stop()

def read_serial_data():
    try:
        with serial.Serial('/dev/ttyUSB0', 9600, parity=serial.PAR_NONE, stopbits=serial.STOPBITS_ONE) as ser:
            while True:
                line = ser.readline().decode('ascii', errors='ignore')
                line = line.strip()
                if line:
                    fields = line.split(',')
                    if len(fields) == 2:
                        heart_rate, sp02 = fields
                        print(f"Heart Rate: {heart_rate} bpm, SpO2: {sp02} %")
                    else:
                        raise ValueError(f"Invalid data: {line}")
                time.sleep(1)
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
    except ValueError as e:
        print(f"Error parsing data: {e}")
    finally:
        if ser is not None:
            ser.close()

def main():
    try:
        connect_to_mqtt()
        read_serial_data()
    except KeyboardInterrupt:
        print("\nExiting...")
        disconnect_from_mqtt()
        led.off()
        button.wait()
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if mqtt_client is not None:
            disconnect_from_mqtt()

if __name__ == "__main__":
    main()

import serial
import time
import datetime
import os
import sys

def main():
    try:
        with serial.Serial('/dev/serial0', 9600, timeout=1, parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE, bytesize=serial.EIGHTBITS) as ser:
            with open('power_consumption.log', 'a') as log_file:
                while True:
                    line = ser.readline().decode('ascii').strip()
                    try:
                        value = float(line)
                        timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                        log_file.write(f"{timestamp} – Power: {value:.2f} W\n")
                    except ValueError:
                        sys.stderr.write(f"Warning: Non-numeric data received: {line}\n")
                    except Exception as e:
                        sys.stderr.write(f"Error: {e}\n")
    except serial.SerialException as e:
        sys.stderr.write(f"Error: {e}\n")
    except OSError as e:
        sys.stderr.write(f"Error: {e}\n")
    finally:
        if 'ser' in locals():
            ser.close()

if __name__ == "__main__":
    main()
